def _compute_batch_average_embed(x: torch.Tensor, num_groups: int) -> torch.Tensor:
    """Compute a normalized projection vector from the batch statistics of ``x``.

    The activations are split into sub-tokens and the mean sub-token (across the flattened batch and group dimensions)
    is used as the shared projection direction, which is then L2-normalized.
    """
    grouped = _reshape_to_grouped_subtokens(x, num_groups)  # (N, num_groups, group_size)
    embed = grouped.mean(dim=(0, 1))  # (group_size,)
    return _normalize_projection(embed)


